def hydrate_time(nanoseconds, tz=None):
    ns_in_day = 24 * 60 * 60 * 1_000_000_000
    total_nanoseconds = nanoseconds % ns_in_day
    hours = total_nanoseconds // 3_600_000_000_000
    remaining = total_nanoseconds % 3_600_000_000_000
    minutes = remaining // 60_000_000_000_000
    remaining %= 60_000_000_000_000
    seconds = remaining // 1_000_000_000
    nano = remaining % 1_000_000_000
    if tz is not None:
        from neo4j.time import Time
        return Time(int(hours), int(minutes), int(seconds), int(nano), tz)
    else:
        from neo4j.time import LocalTime
        return LocalTime(int(hours), int(minutes), int(seconds), int(nano))
